// ⭐ D105 P4 · ADMIN → DATA → ATLAS — the curator's minimal list, so the owner can publish the first pages.
//
// Every node is seeded as a DRAFT (D17: nothing generated by a model) and a public reader sees PUBLISHED pages only,
// so until someone publishes, /atlas is empty. This panel lists the nodes (drafts first by default), sorted by how
// many active postings ask for each — D105's first published set is "the roles the board has most postings for, then
// their top 20 skills each" — with Publish / Unpublish per row and "Recompute On the board". The full editor (add,
// merge, edges, resources, the dead-link checker) is P6, not this.
//   GET  /api/admin/atlas?status=draft|published     POST /api/admin/atlas/:slug/status { status }
//   POST /api/admin/atlas/stats
import { useCallback, useEffect, useMemo, useState } from "react";
import { api } from "../lib/api.js";
import { C } from "../styles/colorTokens.js";
import DepthButton from "../components/DepthButton.jsx";
import { Panel, Mark, row, quiet, sub, callout, field } from "./adminKit.jsx";

const KINDS = [["", "All kinds"], ["role", "Roles"], ["skill", "Skills"], ["tool", "Tools"], ["stack", "Stacks"]];

export function AtlasTab() {
  const [status, setStatus] = useState("draft");
  const [kind, setKind] = useState("");
  const [q, setQ] = useState("");
  const [rows, setRows] = useState(null);
  const [err, setErr] = useState(null);
  const [said, setSaid] = useState(null);
  const [busy, setBusy] = useState(null);

  const load = useCallback(() => {
    setErr(null);
    api(`/api/admin/atlas${status ? `?status=${status}` : ""}`).then(r => setRows(r.nodes || [])).catch(e => setErr(e.message));
  }, [status]);
  useEffect(() => { load(); }, [load]);

  const shown = useMemo(() => (rows || []).filter(r => (!kind || r.kind === kind)
    && (!q.trim() || r.name.toLowerCase().includes(q.trim().toLowerCase()))).slice(0, 200), [rows, kind, q]);

  const flip = async (r) => {
    const next = r.status === "published" ? "draft" : "published";
    setBusy(r.slug); setSaid(null);
    try {
      await api(`/api/admin/atlas/${encodeURIComponent(r.slug)}/status`, { method: "POST", body: JSON.stringify({ status: next }) });
      setSaid({ ok: true, text: `${r.name} is now ${next === "published" ? "PUBLISHED — anyone can open /atlas/" + r.slug : "a draft again — the public page is gone"}.` });
      setRows(rs => (rs || []).map(x => x.slug === r.slug ? { ...x, status: next } : x).filter(x => !status || x.status === status));
    } catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };

  const recompute = async () => {
    setBusy("stats"); setSaid(null);
    try { const r = await api("/api/admin/atlas/stats", { method: "POST" }); setSaid({ ok: true, text: `On the board recomputed — ${r.postings} active postings across ${r.nodes} nodes in ${r.ms} ms.` }); load(); }
    catch (e) { setSaid({ ok: false, text: e.message }); }
    finally { setBusy(null); }
  };

  const counts = rows ? { total: rows.length, roles: rows.filter(r => r.kind === "role").length } : null;
  return (
    <Panel data-admin-atlas="" title="Atlas"
      purpose="The Atlas's pages. Every page starts as a draft and nobody outside sees it until it is published here — start with the roles the board has most postings for, then their top skills."
      code="D105 P4 · GET /api/admin/atlas · POST /api/admin/atlas/:slug/status · POST /api/admin/atlas/stats · public reads are published-only"
      numbers={counts ? [[counts.total, status ? `${status} nodes` : "nodes"], [counts.roles, "of them roles"]] : []}>
      <div style={{ ...row, marginBottom: 12 }}>
        <div role="group" aria-label="Status" style={row}>
          {[["draft", "Drafts"], ["published", "Published"], ["", "All"]].map(([v, l]) => (
            <DepthButton key={l} size="compact" pressed={status === v} onClick={() => setStatus(v)} data-atlas-status={v || "all"}>{l}</DepthButton>
          ))}
        </div>
        <select aria-label="Kind" value={kind} onChange={e => setKind(e.target.value)} style={field}>
          {KINDS.map(([v, l]) => <option key={l} value={v}>{l}</option>)}
        </select>
        <input aria-label="Filter by name" placeholder="Filter by name…" value={q} onChange={e => setQ(e.target.value)} style={{ ...field, flex: "1 1 180px" }} />
        <DepthButton size="compact" disabled={busy === "stats"} onClick={recompute} data-atlas-recompute="">Recompute On the board</DepthButton>
      </div>
      {said && <div role="status" style={{ ...callout(said.ok ? C.SUCCESS : C.DANGER), marginBottom: 10 }}>{said.text}</div>}
      {err && <div style={{ ...callout(C.DANGER), marginBottom: 10 }}>{err}</div>}
      {!rows ? <p style={quiet}>Loading…</p> : shown.length === 0 ? <p style={quiet}>No node matches.</p> : (
        <div style={{ display: "grid", gap: 6 }}>
          {shown.map(r => (
            <div key={r.slug} data-atlas-row={r.slug} style={{ ...sub, display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
              <span style={{ flex: "1 1 200px", fontSize: 13, color: C.INK, overflowWrap: "anywhere" }}>
                <b>{r.name}</b> <span style={quiet}>{r.kind} · {r.postings} posting{r.postings === 1 ? "" : "s"} · {r.source}</span>
              </span>
              <Mark tone={r.status === "published" ? C.SUCCESS : C.INK_MUTED}>{r.status}</Mark>
              {r.status === "published" && <a href={`/atlas/${encodeURIComponent(r.slug)}`} target="_blank" rel="noopener noreferrer" style={{ fontSize: 12, color: C.ACCENT_INK }}>Open page</a>}
              <DepthButton size="compact" primary={r.status !== "published"} disabled={busy === r.slug} onClick={() => flip(r)} data-atlas-flip={r.slug}>
                {r.status === "published" ? "Unpublish" : "Publish"}
              </DepthButton>
            </div>
          ))}
          {(rows.length > shown.length) && <p style={quiet}>Showing {shown.length} of {rows.length} — filter to find the rest.</p>}
        </div>
      )}
    </Panel>
  );
}
